/**
 * The HYT logo as a base64 data URI.
 *
 * Why a data URI and not an ordinary CRA asset import:
 *
 * The printable DTR is rendered into an off-screen IFRAME, then printed.  A
 * CRA asset import resolves to a path like `/static/media/HYT.<hash>.png` - * which the iframe resolves relative to ITS OWN document, not the app's
 * origin.  When that lookup fails the print dialog shows a broken-image icon,
 * and worse, it fails SILENTLY (the on-screen preview still looks fine).
 *
 * Inlining the bytes removes the lookup entirely: no fetch, no relative path,
 * no race between the image loading and `window.print()` being called.
 *
 * ~93 KB of base64.  It lives in its own module so it is only pulled in by the
 * pages that print (DTR here, certificates), never the whole public bundle.
 *
 * Regenerate with:
 *   python -c "import base64;print(base64.b64encode(open('HYT.png','rb').read()).decode())"
 */
export const HYT_LOGO_DATA_URI = 'data:image/png;base64,';

export default HYT_LOGO_DATA_URI;
